const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Toshka Lakes area in Egypt
  const toshka = ee.Geometry.Point([30.5, 22.5]).buffer(30000); // 30km buffer around Toshka Lakes

  // 2. Date ranges
  const date2002_start = '2002-09-01';
  const date2002_end = '2002-09-30';
  const date2012_start = '2012-06-01';
  const date2012_end = '2012-06-30';

  // 3. Helper function to calculate water extent using MNDWI
  function calculateWaterExtent(collection, geometry) {
    const size = collection.size().getInfo();
    if (size === 0) {
      return null;
    }

    // Create composite and calculate MNDWI
    const composite = collection.median();
    const mndwi = composite.normalizedDifference(['B2', 'B5']).rename('mndwi'); // Green - SWIR

    // Threshold for water (MNDWI > 0 typically indicates water)
    const water = mndwi.gt(0);

    // Count water pixels
    const stats = water.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    });

    const waterPixels = stats.get('mndwi').getInfo();
    const totalPixels = water.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 3000,
      maxPixels: 1e9
    }).get('mndwi').getInfo();

    return { waterPixels: waterPixels, totalPixels: totalPixels, imageCount: size };
  }

  // 4. Try Landsat 7 for 2002
  let col2002 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(toshka)
    .filterDate(date2002_start, date2002_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2002 = col2002.size().getInfo();
  console.log(`2002 Landsat 7 images found: ${size2002}`);

  if (size2002 === 0) {
    // Try Landsat 5 for 2002
    col2002 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(toshka)
      .filterDate(date2002_start, date2002_end)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    size2002 = col2002.size().getInfo();
    console.log(`2002 Landsat 5 images found: ${size2002}`);
  }

  if (size2002 === 0) {
    console.log('No data for September 2002.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Try Landsat 7 for 2012
  let col2012 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(toshka)
    .filterDate(date2012_start, date2012_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let size2012 = col2012.size().getInfo();
  console.log(`2012 Landsat 7 images found: ${size2012}`);

  if (size2012 === 0) {
    // Try Landsat 5 for 2012
    col2012 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(toshka)
      .filterDate(date2012_start, date2012_end)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    size2012 = col2012.size().getInfo();
    console.log(`2012 Landsat 5 images found: ${size2012}`);
  }

  if (size2012 === 0) {
    console.log('No data for June 2012.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 6. Calculate water extent for both periods
  const result2002 = calculateWaterExtent(col2002, toshka);
  const result2012 = calculateWaterExtent(col2012, toshka);

  if (result2002 === null || result2012 === null) {
    console.log('Failed to process imagery.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`2002: Water pixels = ${result2002.waterPixels}, Total pixels = ${result2002.totalPixels}`);
  console.log(`2012: Water pixels = ${result2012.waterPixels}, Total pixels = ${result2012.totalPixels}`);

  // 7. Check for valid pixels
  if (result2002.totalPixels === 0 || result2012.totalPixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Check for calculation validity
  if (result2002.waterPixels === null || result2012.waterPixels === null || 
      isNaN(result2002.waterPixels) || isNaN(result2012.waterPixels)) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Compare water extents
  const waterArea2002 = result2002.waterPixels * 9; // 3000m scale = 9 km² per pixel
  const waterArea2012 = result2012.waterPixels * 9;

  console.log(`2002 water area: ${waterArea2002.toFixed(2)} km²`);
  console.log(`2012 water area: ${waterArea2012.toFixed(2)} km²`);
  console.log(`Change: ${(waterArea2012 - waterArea2002).toFixed(2)} km²`);

  // 10. Final answer
  if (waterArea2012 < waterArea2002) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
